'use strict';

function makeDensityGrid(points, width, height, options = {}) {
  if (!Array.isArray(points)) throw new TypeError('points must be an array');
  if (!Number.isInteger(width) || !Number.isInteger(height)) throw new TypeError('dimensions must be integers');
  if (width <= 0 || height <= 0) throw new RangeError('dimensions must be positive');
  if (!options || typeof options !== 'object' || Array.isArray(options)) throw new TypeError('options must be an object');
  const radius = options.radius === undefined ? 0 : options.radius;
  const cap = options.cap === undefined ? Infinity : options.cap;
  if (!Number.isInteger(radius)) throw new TypeError('radius must be an integer');
  if (radius < 0) throw new RangeError('radius must be non-negative');
  if (typeof cap !== 'number' || Number.isNaN(cap)) throw new TypeError('cap must be numeric');
  if (cap <= 0) throw new RangeError('cap must be positive');

  const grid = Array(height).fill(Array(width).fill(0));
  for (const point of points) {
    if (!point || typeof point !== 'object' || Array.isArray(point)) throw new TypeError('invalid point');
    if (!Number.isInteger(point.x) || !Number.isInteger(point.y)) throw new TypeError('coordinates must be integers');
    if (point.x < 0 || point.x >= width || point.y < 0 || point.y >= height) throw new RangeError('point out of bounds');
    if (typeof point.weight !== 'number' || !Number.isFinite(point.weight)) throw new TypeError('weight must be finite');
    if (point.weight < 0) throw new RangeError('weight must be non-negative');
    for (let y = Math.max(0, point.y - radius); y <= Math.min(height - 1, point.y + radius); y++) {
      for (let x = Math.max(0, point.x - radius); x <= Math.min(width - 1, point.x + radius); x++) {
        if ((x - point.x) ** 2 + (y - point.y) ** 2 <= radius ** 2) {
          grid[y][x] = Math.min(cap, grid[y][x] + point.weight);
        }
      }
    }
  }
  return grid;
}

module.exports = { makeDensityGrid };

