'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['makeDensityGrid']);
const { makeDensityGrid } = api;

const empty = makeDensityGrid([], 3, 2);
assert.deepStrictEqual(empty, [[0, 0, 0], [0, 0, 0]]);
assert.notStrictEqual(empty[0], empty[1]);
empty[0][0] = 9;
assert.strictEqual(empty[1][0], 0);

const points = [
  { x: 1, y: 1, weight: 2 },
  { x: 0, y: 0, weight: 1.5 }
];
const pointsBefore = points.map(p => ({ ...p }));
const options = { radius: 1, cap: 2.5 };
const optionsBefore = { ...options };
const grid = makeDensityGrid(points, 3, 3, options);
assert.deepStrictEqual(grid, [
  [1.5, 2.5, 0],
  [2.5, 2, 2],
  [0, 2, 0]
]);
assert.deepStrictEqual(points, pointsBefore);
assert.deepStrictEqual(options, optionsBefore);

assert.deepStrictEqual(makeDensityGrid([{ x: 0, y: 0, weight: 3 }], 2, 1, { cap: 2 }), [[2, 0]]);
assert.deepStrictEqual(makeDensityGrid([{ x: 1, y: 0, weight: 0 }], 2, 1, { radius: 0 }), [[0, 0]]);

for (const bad of [0, -1, 1.5, NaN, Infinity, '2']) {
  assert.throws(() => makeDensityGrid([], bad, 2), e => e instanceof TypeError || e instanceof RangeError);
  assert.throws(() => makeDensityGrid([], 2, bad), e => e instanceof TypeError || e instanceof RangeError);
}
assert.throws(() => makeDensityGrid(null, 2, 2), TypeError);
assert.throws(() => makeDensityGrid([null], 2, 2), TypeError);
assert.throws(() => makeDensityGrid([[0, 0]], 2, 2), TypeError);
assert.throws(() => makeDensityGrid([{ x: 0.5, y: 0, weight: 1 }], 2, 2), e => e instanceof TypeError || e instanceof RangeError);
assert.throws(() => makeDensityGrid([{ x: -1, y: 0, weight: 1 }], 2, 2), e => e instanceof TypeError || e instanceof RangeError);
assert.throws(() => makeDensityGrid([{ x: 2, y: 0, weight: 1 }], 2, 2), e => e instanceof TypeError || e instanceof RangeError);
assert.throws(() => makeDensityGrid([{ x: 0, y: 0, weight: -1 }], 2, 2), e => e instanceof TypeError || e instanceof RangeError);
assert.throws(() => makeDensityGrid([{ x: 0, y: 0, weight: Infinity }], 2, 2), e => e instanceof TypeError || e instanceof RangeError);
assert.throws(() => makeDensityGrid([], 2, 2, null), TypeError);
assert.throws(() => makeDensityGrid([], 2, 2, []), TypeError);
assert.throws(() => makeDensityGrid([], 2, 2, { radius: -1 }), e => e instanceof TypeError || e instanceof RangeError);
assert.throws(() => makeDensityGrid([], 2, 2, { radius: 1.2 }), e => e instanceof TypeError || e instanceof RangeError);
assert.throws(() => makeDensityGrid([], 2, 2, { cap: 0 }), e => e instanceof TypeError || e instanceof RangeError);
assert.throws(() => makeDensityGrid([], 2, 2, { cap: NaN }), e => e instanceof TypeError || e instanceof RangeError);

